package golang

import (
	compiler "openapi-sdkgen/internal/compiler"
	"openapi-sdkgen/internal/generator"
	"testing"
)

func TestGeneratedStreamingRequestSources(t *testing.T) {
	document, err := compiler.Compile([]byte(`{"openapi":"3.2.0","info":{"title":"Stream requests","version":"1"},"paths":{"/upload":{"post":{"operationId":"uploadNumbers","requestBody":{"required":true,"content":{"application/x-ndjson":{"itemSchema":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}}}},"responses":{"204":{"description":"Done"}}}},"/both":{"post":{"operationId":"echoNumbers","requestBody":{"required":true,"content":{"application/x-ndjson":{"schema":{"type":"array","items":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}},"itemSchema":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}}}},"responses":{"200":{"description":"Echo","content":{"application/x-ndjson":{"schema":{"type":"array","items":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}},"itemSchema":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}}}}}}},"/buffered":{"post":{"operationId":"bufferedNumbers","requestBody":{"required":true,"content":{"application/x-ndjson":{"schema":{"type":"array","items":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}}}}},"responses":{"204":{"description":"Done"}}}},"/events":{"post":{"operationId":"uploadEvents","requestBody":{"required":true,"content":{"text/event-stream":{"itemSchema":{"type":"object","required":["data"],"properties":{"data":{"type":"string","minLength":1},"id":{"type":"string"}}}}}},"responses":{"204":{"description":"Done"}}}},"/seq":{"post":{"operationId":"uploadSequence","requestBody":{"required":true,"content":{"application/json-seq":{"itemSchema":{"type":"integer"}}}},"responses":{"204":{"description":"Done"}}}},"/custom":{"post":{"operationId":"uploadCustom","requestBody":{"required":true,"content":{"application/vnd.frames":{"itemSchema":{"type":"object","required":["id"],"properties":{"id":{"type":"integer"}}}}}},"responses":{"204":{"description":"Done"}}}},"/files":{"post":{"operationId":"uploadFiles","requestBody":{"required":true,"content":{"multipart/mixed":{"itemSchema":{"type":"string","format":"binary"},"itemEncoding":{"contentType":"application/octet-stream"}}}},"responses":{"204":{"description":"Done"}}}}}}`))
	if err != nil {
		t.Fatal(err)
	}
	plan, diagnostics, err := (Generator{}).Prepare(document, generator.Options{Golang: &generator.GoOptions{ImportPath: "example.test/consumer/api"}})
	if err != nil || len(diagnostics) != 0 {
		t.Fatalf("prepare %v %v", err, diagnostics)
	}
	testGeneratedModule(t, plan, map[string]string{"stream_request_test.go": streamRequestConsumer, "stream_request_http_test.go": streamRequestHTTPConsumer})
}

const streamRequestConsumer = `package consumer_test
import("bytes";"context";"errors";"io";"mime";"mime/multipart";"net/http";"strings";"sync/atomic";"testing";sdk "example.test/consumer/api";"example.test/consumer/api/models";"example.test/consumer/api/types")
type requestStats struct{factories,next,closes atomic.Int32;requireCancel bool}
type requestItems[T any] struct{ctx context.Context;items []T;index int;stats *requestStats}
func(source *requestItems[T])Next()bool{source.stats.next.Add(1);if source.ctx.Err()!=nil||source.index==len(source.items){return false};source.index++;return true}
func(source *requestItems[T])Item()T{return source.items[source.index-1]}
func(source *requestItems[T])Err()error{return source.ctx.Err()}
func(source *requestItems[T])Close()error{source.stats.closes.Add(1);if source.stats.requireCancel&&source.ctx.Err()==nil{return errors.New("factory context was not canceled before close")};return nil}
func itemFactory[T any](stats *requestStats,items []T)types.SourceFactory[T]{return func(ctx context.Context)(types.Source[T],error){stats.factories.Add(1);return &requestItems[T]{ctx:ctx,items:items,stats:stats},nil}}
type requestTransport struct{calls atomic.Int32;inspect func(*http.Request)(*http.Response,error)}
func(*requestTransport)Capabilities()types.TransportCapabilities{return types.TransportCapabilities{}}
func(transport *requestTransport)Do(request *http.Request,_ types.TransportOptions)(*http.Response,error){transport.calls.Add(1);return transport.inspect(request)}
func requestClient(t *testing.T,transport *requestTransport,codecs ...map[string]types.StreamCodec)*sdk.Client{t.Helper();options:=sdk.ClientOptions{BaseURL:"https://example.test",Transport:transport};if len(codecs)!=0{options.StreamCodecs=codecs[0]};client,err:=sdk.NewClient(options);if err!=nil{t.Fatal(err)};return client}
func emptyRequestResponse(request *http.Request)*http.Response{return &http.Response{StatusCode:204,Header:make(http.Header),Body:http.NoBody,Request:request}}
func TestIncrementalRequestsAreLazyReusableAndOwned(t *testing.T){
 stats:=&requestStats{requireCancel:true};transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){if stats.factories.Load()!=transportFactoryExpectation.Load()||stats.next.Load()!=transportNextExpectation.Load(){t.Error("factory/Next ordering",stats.factories.Load(),stats.next.Load())};defer request.Body.Close();data,err:=io.ReadAll(request.Body);if err!=nil{return nil,err};if string(data)!="{\"id\":1}\n{\"id\":2}\n"||request.Header.Get("Content-Type")!="application/x-ndjson"{t.Error("NDJSON request",string(data),request.Header)};return emptyRequestResponse(request),nil}}
 client:=requestClient(t,transport);factory:=itemFactory(stats,[]sdk.UploadNumbersRequestItem{ {ID:1},{ID:2} });call:=client.Operations.UploadNumbers(sdk.UploadNumbersInput{Body:factory});if stats.factories.Load()!=0||stats.next.Load()!=0{t.Fatal("call construction opened source")}
 for index:=int32(0);index<2;index++{transportFactoryExpectation.Store(index+1);transportNextExpectation.Store(index*3);if _,err:=call.Do(context.Background());err!=nil{t.Fatal(err)}};if stats.factories.Load()!=2||stats.closes.Load()!=2{t.Fatal("factory reuse/close",stats.factories.Load(),stats.closes.Load())}
}
var transportFactoryExpectation,transportNextExpectation atomic.Int32
func TestCompleteAndIncrementalTaggedBodiesAndRawEcho(t *testing.T){
 transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();data,err:=io.ReadAll(request.Body);if err!=nil{return nil,err};if string(data)!="{\"id\":3}\n{\"id\":4}\n"{t.Error("tagged request bytes",string(data))};return &http.Response{StatusCode:200,Header:http.Header{"Content-Type":{"application/x-ndjson"}},Body:io.NopCloser(bytes.NewReader(data)),Request:request},nil}}
 client:=requestClient(t,transport);value,_:=types.ParseValue([]byte("[{\"id\":3},{\"id\":4}]"));complete,err:=models.DecodeEchoNumbersCompleteBody(context.Background(),value);if err!=nil{t.Fatal(err)}
 result,err:=client.Operations.EchoNumbers(sdk.EchoNumbersInput{Body:sdk.NewEchoNumbersCompleteBody(complete)}).Do(context.Background());if err!=nil||len(result)!=2||result[0].ID!=3{t.Fatal("complete tagged",result,err)}
 stats:=&requestStats{requireCancel:true};factory:=itemFactory(stats,[]sdk.EchoNumbersRequestItem{ {ID:3},{ID:4} });handle:=client.Operations.EchoNumbers(sdk.EchoNumbersInput{Body:sdk.NewEchoNumbersStreamBody(factory)}).Stream(context.Background());count:=0;for handle.Next(){count++;if handle.Item().ID!=float64(count+2){t.Fatal("echo item",handle.Item())}};handle.Close();if count!=2||handle.Err()!=nil||stats.closes.Load()!=1{t.Fatal("incremental tagged",count,handle.Err(),stats.closes.Load())}
 before:=transport.calls.Load();if _,err:=client.Operations.EchoNumbers(sdk.EchoNumbersInput{}).Do(context.Background());err==nil||transport.calls.Load()!=before{t.Fatal("zero body tag accepted",err)}
}
func TestFactoryAndItemFailuresAndOneShot(t *testing.T){
 transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();if _,err:=io.Copy(io.Discard,request.Body);err!=nil{return nil,err};return emptyRequestResponse(request),nil}};client:=requestClient(t,transport);var failure *types.APIError
 if _,err:=client.Operations.UploadNumbers(sdk.UploadNumbersInput{}).Do(context.Background());!errors.As(err,&failure)||failure.Code!=types.RequestEncodeFailed||transport.calls.Load()!=0{t.Fatal("nil factory",err)}
 sentinel:=errors.New("factory failed");stats:=&requestStats{requireCancel:true};bad:=func(ctx context.Context)(types.Source[sdk.UploadNumbersRequestItem],error){return &requestItems[sdk.UploadNumbersRequestItem]{ctx:ctx,stats:stats},sentinel};if _,err:=client.Operations.UploadNumbers(sdk.UploadNumbersInput{Body:bad}).Do(context.Background());!errors.Is(err,sentinel)||stats.closes.Load()!=1||transport.calls.Load()!=0{t.Fatal("factory error cleanup",err,stats.closes.Load())}
 typedNil:=func(context.Context)(types.Source[sdk.UploadNumbersRequestItem],error){var source *requestItems[sdk.UploadNumbersRequestItem];return source,nil};if _,err:=client.Operations.UploadNumbers(sdk.UploadNumbersInput{Body:typedNil}).Do(context.Background());err==nil||transport.calls.Load()!=0{t.Fatal("typed nil factory result",err)}
 invalidStats:=&requestStats{requireCancel:true};if _,err:=client.Operations.UploadNumbers(sdk.UploadNumbersInput{Body:itemFactory(invalidStats,[]sdk.UploadNumbersRequestItem{ {ID:1.5} })}).Do(context.Background());!errors.As(err,&failure)||failure.Code!=types.RequestEncodeFailed||invalidStats.closes.Load()!=1{t.Fatal("item validation",err,invalidStats.closes.Load())}
 onceStats:=&requestStats{};source:=&requestItems[sdk.UploadNumbersRequestItem]{ctx:context.Background(),stats:onceStats,items:[]sdk.UploadNumbersRequestItem{ {ID:1} }};factory:=types.SourceOnce[sdk.UploadNumbersRequestItem](source);call:=client.Operations.UploadNumbers(sdk.UploadNumbersInput{Body:factory});copy:=call;if _,err:=call.Do(context.Background());err!=nil{t.Fatal(err)};before:=transport.calls.Load();if _,err:=copy.Do(context.Background());!errors.As(err,&failure)||failure.Code!=types.RequestEncodeFailed||transport.calls.Load()!=before{t.Fatal("one-shot source replayed",err)};if onceStats.closes.Load()!=1{t.Fatal("one-shot close count",onceStats.closes.Load())}
}
func TestSchemaOnlyAndOtherNativeRequestFrames(t *testing.T){
 transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();data,err:=io.ReadAll(request.Body);if err!=nil{return nil,err};expected:="";switch request.URL.Path{case "/buffered":expected="{\"id\":7}\n";case "/events":expected="data: one\ndata: two\nid: e1\n\n";case "/seq":expected="\x1e1\n\x1e2\n"};if string(data)!=expected{t.Error("native request",request.URL.Path,string(data),expected)};return emptyRequestResponse(request),nil}};client:=requestClient(t,transport)
 value,_:=types.ParseValue([]byte("[{\"id\":7}]"));complete,err:=models.DecodeBufferedNumbersBody(context.Background(),value);if err!=nil{t.Fatal(err)};if _,err:=client.Operations.BufferedNumbers(sdk.BufferedNumbersInput{Body:complete}).Do(context.Background());err!=nil{t.Fatal(err)}
 events:=itemFactory(&requestStats{requireCancel:true},[]sdk.UploadEventsRequestItem{ {Data:"one\ntwo",ID:types.Some("e1")} });if _,err:=client.Operations.UploadEvents(sdk.UploadEventsInput{Body:events}).Do(context.Background());err!=nil{t.Fatal(err)}
 sequence:=itemFactory(&requestStats{requireCancel:true},[]sdk.UploadSequenceRequestItem{1,2});if _,err:=client.Operations.UploadSequence(sdk.UploadSequenceInput{Body:sequence}).Do(context.Background());err!=nil{t.Fatal(err)}
}
type fileProbe struct{size int64;unknown bool;opens,closes atomic.Int32;read atomic.Int64}
func(source *fileProbe)Metadata()types.BinaryMetadata{metadata:=types.BinaryMetadata{Filename:"big.bin"};if !source.unknown{metadata.Size=types.Some(source.size)};return metadata}
func(source *fileProbe)Open(ctx context.Context)(io.ReadCloser,error){source.opens.Add(1);return &fileProbeReader{source:source,ctx:ctx,remaining:source.size},nil}
type fileProbeReader struct{source *fileProbe;ctx context.Context;remaining int64}
func(reader *fileProbeReader)Read(buffer []byte)(int,error){if err:=reader.ctx.Err();err!=nil{return 0,err};if reader.remaining==0{return 0,io.EOF};count:=len(buffer);if int64(count)>reader.remaining{count=int(reader.remaining)};clear(buffer[:count]);reader.remaining-=int64(count);reader.source.read.Add(int64(count));return count,nil}
func(reader *fileProbeReader)Close()error{reader.source.closes.Add(1);return nil}
func TestNativeIncrementalMultipartDoesNotBufferFiles(t *testing.T){
 file:=&fileProbe{size:64<<20};stats:=&requestStats{requireCancel:true};transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();if stats.factories.Load()!=1||stats.next.Load()!=0||file.opens.Load()!=0{t.Error("eager multipart source",stats.factories.Load(),stats.next.Load(),file.opens.Load())};header:=make([]byte,256);count,err:=request.Body.Read(header);if err!=nil||count==0||!strings.Contains(string(header[:count]),"Content-Type: application/octet-stream")||file.opens.Load()!=0||file.read.Load()!=0{t.Error("file opened before header was consumed",count,err,file.opens.Load(),file.read.Load())};if _,err:=io.Copy(io.Discard,request.Body);err!=nil{return nil,err};return emptyRequestResponse(request),nil}}
 client:=requestClient(t,transport);factory:=itemFactory(stats,[]sdk.UploadFilesRequestItem{sdk.UploadFilesRequestItem(types.BinaryFromSource(file))});if _,err:=client.Operations.UploadFiles(sdk.UploadFilesInput{Body:factory}).WithOptions(types.RequestOptions{MaxStreamFrameBytes:types.Some(64<<20)}).Do(context.Background());err!=nil{t.Fatal(err)};if file.opens.Load()!=1||file.closes.Load()!=1||file.read.Load()!=64<<20||stats.closes.Load()!=1{t.Fatal("large file lifetime",file.opens.Load(),file.closes.Load(),file.read.Load(),stats.closes.Load())}
}
func TestNativeMultipartRequestLimitAndEarlyResponse(t *testing.T){
 for _,unknown:=range []bool{false,true}{file:=&fileProbe{size:32,unknown:unknown};stats:=&requestStats{requireCancel:true};transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();_,err:=io.Copy(io.Discard,request.Body);if err!=nil{return nil,err};return emptyRequestResponse(request),nil}};client:=requestClient(t,transport);factory:=itemFactory(stats,[]sdk.UploadFilesRequestItem{sdk.UploadFilesRequestItem(types.BinaryFromSource(file))});_,err:=client.Operations.UploadFiles(sdk.UploadFilesInput{Body:factory}).WithOptions(types.RequestOptions{MaxStreamFrameBytes:types.Some(8)}).Do(context.Background());var frame *types.StreamFrameError;if !errors.As(err,&frame)||frame.Kind!="limit"||stats.closes.Load()!=1{t.Fatal("multipart bound",unknown,err,stats.closes.Load())};if unknown{if file.read.Load()!=9||file.closes.Load()!=1{t.Fatal("unknown-size bounded read",file.read.Load(),file.closes.Load())}}else if file.opens.Load()!=0{t.Fatal("oversized known file was opened")}}
 file:=&fileProbe{size:64<<20};stats:=&requestStats{requireCancel:true};transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){return emptyRequestResponse(request),nil}};client:=requestClient(t,transport);factory:=itemFactory(stats,[]sdk.UploadFilesRequestItem{sdk.UploadFilesRequestItem(types.BinaryFromSource(file))});if _,err:=client.Operations.UploadFiles(sdk.UploadFilesInput{Body:factory}).Do(context.Background());err!=nil{t.Fatal(err)};if stats.factories.Load()!=1||stats.next.Load()!=0||stats.closes.Load()!=1||file.opens.Load()!=0{t.Fatal("early response lifetime",stats.factories.Load(),stats.next.Load(),stats.closes.Load(),file.opens.Load())}
}
func TestMultipartFactoryUsesActualPositionalWire(t *testing.T){
 transport:=&requestTransport{inspect:func(request *http.Request)(*http.Response,error){defer request.Body.Close();_,parameters,err:=mime.ParseMediaType(request.Header.Get("Content-Type"));if err!=nil{return nil,err};reader:=multipart.NewReader(request.Body,parameters["boundary"]);part,err:=reader.NextPart();if err!=nil{return nil,err};data,err:=io.ReadAll(part);if err!=nil{return nil,err};if string(data)!="one"||part.Header.Get("Content-Type")!="application/octet-stream"{t.Error("binary part",part.Header,string(data))};if _,err:=reader.NextPart();err!=io.EOF{return nil,errors.New("multipart did not terminate")};return emptyRequestResponse(request),nil}};client:=requestClient(t,transport);factory:=itemFactory(&requestStats{requireCancel:true},[]sdk.UploadFilesRequestItem{sdk.UploadFilesRequestItem(types.BinaryFromString("one"))});if _,err:=client.Operations.UploadFiles(sdk.UploadFilesInput{Body:factory}).Do(context.Background());err!=nil{t.Fatal(err)}
}
`
